// D2: spawnSync with argv array (never via shell) — avoids D18 (inherited errexit).
//   timeout: 30 000 ms; expired → error.code=ETIMEDOUT → fail-closed.
//
// D3 Payload: {"hook_source":"opencode","tool_name":<name>,"tool_input":<args>,"cwd":<root>}
//   hook_source:"opencode" enables the read scan in the Go guard (ADR D3/D4).

"use strict"

const childProcess = require("node:child_process")
const nodePath = require("node:path")
const nodeOS = require("node:os")
const fs = require("node:fs")

// SCOPE: "project" for the project plugin; "global" for the global plugin.
// This is the ONLY line that differs between the two generated files.
const SCOPE = "project"

// SHELL_TOOLS: shell tool IDs in V1 ("bash") and V2 ("shell")
const SHELL_TOOLS = new Set(["bash", "shell"])

// FILE_WRITE_TOOLS: write tool IDs (ADR D3)
const FILE_WRITE_TOOLS = new Set(["write", "edit", "patch", "apply_patch"])

// FILE_READ_TOOLS: read and grep tool IDs (ADR D3, D7 F6)
const FILE_READ_TOOLS = new Set(["read", "grep"])

// WEBFETCH_TOOLS: webfetch and websearch tool IDs (ADR D3, D7 F6).
// websearch submits a query to a remote service — a secret in the query exfiltrates
// identically to a secret in a webfetch URL (ML-5I2, REQ-2026-11-17).
const WEBFETCH_TOOLS = new Set(["webfetch", "websearch"])

// realpathOrParent resolves symlinks via fs.realpathSync. When the target does
// not exist, it walks up to the nearest existing ancestor, resolves that via
// realpathSync, and reattaches the unresolved tail — preserving the original
// case of path components that could not be resolved (F2/F8).
//
// N7b (ML-5I7): when p is a dangling symlink (lstatSync succeeds, isSymbolicLink=true,
// but realpathSync throws because the target does not exist), the link target is read
// via readlinkSync and resolved against the REAL parent of the link (not the lexical
// parent) using recursive realpathOrParent calls. The recursion is guarded by a depth
// counter that THROWS at >40 levels (fail-closed). The recursive calls are placed
// OUTSIDE any try/catch so the depth-limit throw propagates to the caller.
function realpathOrParent(p, _depth) {
  if (_depth === undefined) { _depth = 0 }
  if (_depth > 40) {
    throw new Error("trackfw-guard: blocked — symlink chain too deep or cycle detected (D4 self-protection)")
  }
  try { return fs.realpathSync(p) } catch (e1) {}
  // N7b: p might be a dangling symlink — detect and follow it before the ancestor walk.
  var linkTarget = null
  try {
    var lst = fs.lstatSync(p)
    if (lst.isSymbolicLink()) {
      linkTarget = fs.readlinkSync(p)
    }
  } catch (e2) {}
  // IMPORTANT: recursive calls are OUTSIDE the try/catch above so that a depth-limit
  // throw from the recursion propagates to the caller (fail-closed for deep chains).
  if (linkTarget !== null) {
    // Resolve the link target relative to the REAL parent of the link so that relative
    // symlinks (e.g. ".opencode/plugins/evil.js") expand correctly even when the
    // link's lexical parent is itself a symlink.
    var realBase = realpathOrParent(nodePath.dirname(p), _depth + 1)
    return realpathOrParent(nodePath.resolve(realBase, linkTarget), _depth + 1)
  }
  var abs = nodePath.resolve(p)
  var parts = abs.split(nodePath.sep)
  for (var len = parts.length - 1; len >= 1; len--) {
    var ancestor = parts.slice(0, len).join(nodePath.sep) || nodePath.sep
    try {
      var resolved = fs.realpathSync(ancestor)
      var tail = parts.slice(len).join(nodePath.sep)
      return nodePath.join(resolved, tail)
    } catch (e3) {}
  }
  return abs
}

// isUnderDir returns true when resolvedTarget is strictly under dir
// (separator-boundary check). Case-insensitive on darwin and win32 (F2/F4).
//
// N8 (ML-5I7): on darwin and win32, both sides are normalised to NFC before
// case-folding. macOS APFS is normalisation-insensitive (NFC and NFD resolve to
// the same inode) but normalisation-preserving (fs.realpathSync returns the input
// form without canonicalising). Without NFC normalisation, isUnderDir(NFD, NFC)
// returns false even though they refer to the same directory.
function isUnderDir(resolvedTarget, dir) {
  var normalDir = nodePath.resolve(dir)
  var sep = nodePath.sep
  var prefix = normalDir.endsWith(sep) ? normalDir : normalDir + sep
  if (process.platform === "darwin" || process.platform === "win32") {
    return resolvedTarget.normalize('NFC').toLowerCase().startsWith(prefix.normalize('NFC').toLowerCase())
  }
  return resolvedTarget.startsWith(prefix)
}

// pathsEqual compares two paths for equality. a is expected to be a
// realpathOrParent-resolved path; b is normalized with nodePath.resolve.
// Case-insensitive on darwin and win32 (F2).
//
// N8 (ML-5I7): on darwin and win32, both sides are normalised to NFC before
// case-folding for the same reason as isUnderDir (APFS normalization-preserving).
function pathsEqual(a, b) {
  var normB = nodePath.resolve(b)
  if (process.platform === "darwin" || process.platform === "win32") {
    return a.normalize('NFC').toLowerCase() === normB.normalize('NFC').toLowerCase()
  }
  return a === normB
}

// unquoteGitPath decodes a git C-string-quoted path token. If the token is not
// surrounded by double-quotes it is returned as-is (trimmed). When quoted, the
// C-style escape sequences used by git are decoded:
//   \\ \" \a \b \f \n \r \t \v — single-char escapes
//   \NNN                       — three-digit octal (N in [0-3][0-7][0-7])
// A malformed quoted token (unterminated, unknown escape, truncated octal)
// throws fail-closed rather than being skipped — skipping would allow a mixed
// patch to supply an innocent candidate that bypasses F5 (ML-5I4).
function unquoteGitPath(s) {
  s = s.trim()
  if (s.length === 0 || s[0] !== '"') { return s }
  if (s[s.length - 1] !== '"') {
    throw new Error(
      "trackfw-guard: blocked — patch with malformed quoted path header " +
      "cannot be verified and is not permitted (D4 fail-closed F5)"
    )
  }
  var inner = s.slice(1, s.length - 1)
  var bytes = []
  for (var i = 0; i < inner.length; i++) {
    if (inner[i] !== '\\') {
      bytes.push(inner.charCodeAt(i))
      continue
    }
    i++
    if (i >= inner.length) {
      throw new Error(
        "trackfw-guard: blocked — patch with malformed quoted path header " +
        "cannot be verified and is not permitted (D4 fail-closed F5)"
      )
    }
    var c = inner[i]
    // Three-digit octal: \[0-3][0-7][0-7]
    if (c >= '0' && c <= '3' && i + 2 < inner.length) {
      var oct = c + inner[i + 1] + inner[i + 2]
      if (/^[0-3][0-7]{2}$/.test(oct)) {
        bytes.push(parseInt(oct, 8))
        i += 2
        continue
      }
    }
    var ESC = { 'a': 7, 'b': 8, 'f': 12, 'n': 10, 'r': 13, 't': 9, 'v': 11, '\\': 92, '"': 34 }
    if (!(c in ESC)) {
      throw new Error(
        "trackfw-guard: blocked — patch with malformed quoted path header " +
        "cannot be verified and is not permitted (D4 fail-closed F5)"
      )
    }
    bytes.push(ESC[c])
  }
  return Buffer.from(bytes).toString("utf8")
}

// parseDiffGitTokens parses the two path tokens from a "diff --git A B" line.
// Each token may be a C-string-quoted path ("...") or an unquoted path with
// no spaces. Returns [rawA, rawB] or null if the line does not start with
// "diff --git ".
function parseDiffGitTokens(line) {
  if (!line.startsWith("diff --git ")) { return null }
  var rest = line.slice("diff --git ".length)
  var tokens = []
  var i = 0
  while (i < rest.length && tokens.length < 2) {
    while (i < rest.length && rest[i] === ' ') { i++ }
    if (i >= rest.length) { break }
    if (rest[i] === '"') {
      // Quoted token: scan to the matching closing quote (respecting escapes).
      var j = i + 1
      while (j < rest.length) {
        if (rest[j] === '\\') { j += 2; continue }
        if (rest[j] === '"') { j++; break }
        j++
      }
      tokens.push(rest.slice(i, j))
      i = j
    } else {
      // Unquoted token: ends at the next space or end of string.
      var j = i
      while (j < rest.length && rest[j] !== ' ') { j++ }
      tokens.push(rest.slice(i, j))
      i = j
    }
  }
  return tokens.length === 2 ? tokens : null
}

// extractPatchTargets parses OpenAI-patch and unified-diff headers to extract
// target file paths (A7/F5). Relative paths are resolved against projectDir.
// Recognized headers:
//   *** Update File: <path>
//   *** Add File:    <path>
//   *** Delete File: <path>
//   *** Move to:     <path>
//   +++ <path>[\t<date>]
//   --- <path>[\t<date>]   (skipped for /dev/null)
//   diff --git <a-path> <b-path>  (git format; N4-ML5I4)
//   rename from <path>            (git rename; N4-ML5I4)
//   rename to   <path>            (git rename; N4-ML5I4)
//   copy from   <path>            (git copy; N4-ML5I4)
//   copy to     <path>            (git copy; N4-ML5I4)
//
// N2: unified diff headers may carry an "a/" or "b/" prefix (git diff default).
// Both the prefixed form and the stripped form are added as candidates — this
// avoids overblocking patches targeting a real directory literally named "a/"
// or "b/" while ensuring the stripped form is always checked.
// N4 (ML-5I4): git rename/copy headers and diff --git lines are now recognized.
// Paths in any header may be C-string-quoted (git quoting for paths with
// special chars or bytes); unquoteGitPath decodes them, including \NNN octal.
function extractPatchTargets(patchText, projectDir) {
  var targets = []
  var lines = patchText.split(/\r?\n/)
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i]
    var m
    // OpenAI patch format headers
    if ((m = line.match(/^\*\*\* (?:Update File|Add File|Delete File|Move to):\s+(.+)$/))) {
      targets.push(nodePath.resolve(projectDir, m[1].trim()))
    } else if ((m = line.match(/^(?:\+\+\+|---)\s+(.+?)(?:\t.*)?$/))) {
      // Unified diff header — skip /dev/null; unquote C-string-quoted paths (N4).
      var rawP = m[1].trim()
      var p = unquoteGitPath(rawP)
      if (p !== "/dev/null" && p !== "dev/null") {
        // N2: add the raw form (handles real dirs named "a/" or "b/")
        targets.push(nodePath.resolve(projectDir, p))
        // N2: also add the a/b-stripped form (the path apply_patch actually writes)
        if (/^[ab]\//.test(p)) {
          targets.push(nodePath.resolve(projectDir, p.slice(2)))
        }
      }
    } else {
      // N4 (ML-5I4): git diff --git and rename/copy headers.
      var gitTokens = parseDiffGitTokens(line)
      if (gitTokens) {
        // diff --git a/X b/Y — add both paths (and their a/b-stripped forms).
        var pathA = unquoteGitPath(gitTokens[0])
        var pathB = unquoteGitPath(gitTokens[1])
        targets.push(nodePath.resolve(projectDir, pathA))
        if (/^a\//.test(pathA)) { targets.push(nodePath.resolve(projectDir, pathA.slice(2))) }
        targets.push(nodePath.resolve(projectDir, pathB))
        if (/^b\//.test(pathB)) { targets.push(nodePath.resolve(projectDir, pathB.slice(2))) }
      } else if ((m = line.match(/^(?:rename|copy) (?:from|to)\s+("(?:[^"\\]|\\.)*"|.+)$/))) {
        // rename from/to or copy from/to — literal path (no a/b prefix in practice).
        var rawRename = m[1].trim()
        var pRename = unquoteGitPath(rawRename)
        targets.push(nodePath.resolve(projectDir, pRename))
        if (/^[ab]\//.test(pRename)) { targets.push(nodePath.resolve(projectDir, pRename.slice(2))) }
      }
    }
  }
  return targets
}

// globalOpenCodeConfigDir returns the GLOBAL OpenCode config directory,
// using the same precedence as Go (agentconfig.OpenCodeConfigDir):
//   1. OPENCODE_CONFIG_DIR (if non-empty) — R-1: a relative value is resolved
//      against process.cwd() (same behaviour as Go filepath.Abs; A2 fix).
//   2. XDG_CONFIG_HOME/opencode (if XDG_CONFIG_HOME is non-empty)
//   3. <home>/.config/opencode  — <home> is nodeOS.homedir(), which on win32
//      returns USERPROFILE (same as os.UserHomeDir() in Go).
//
// D4: never call on the hot path (runs on every tool call) — reading env is
// fast, but computing dirname(dirname(__filename)) only works when __filename
// is already in the GLOBAL plugins directory, which is true only for the global
// plugin. The project plugin lives under .opencode/plugins/ and
// dirname(dirname(__filename)) would point to the project directory, not the
// global config directory — so the protection would be empty or wrong.
function globalOpenCodeConfigDir() {
  var envDir = (process.env.OPENCODE_CONFIG_DIR || "").trim()
  if (envDir) {
    return nodePath.resolve(envDir)  // A2: resolve relative paths
  }
  var xdg = (process.env.XDG_CONFIG_HOME || "").trim()
  if (xdg) {
    return nodePath.join(xdg, "opencode")
  }
  return nodePath.join(nodeOS.homedir(), ".config", "opencode")
}

// selfProtect checks whether the write tool targets any protected path and
// throws if so (D4). Protected paths are:
//   - Any file under dirname(realpathSync(__filename)) — the actual plugin dir
//   - Any file under <projectDir>/.opencode/plugins/ or .opencode/plugin/
//   - Any file under <globalDir>/plugins/ or <globalDir>/plugin/
//   - Protected config files: opencode.json / opencode.jsonc (project + global)
//
// N1: protectedDirs and protectedFiles are resolved via realpathOrParent so that
// a symlinked projectDir or OPENCODE_CONFIG_DIR (e.g. dotfile manager pattern
// ~/.config → /data/config) does not create a bypass.
//
// F7: candidates are collected from ALL present path fields (filePath, path,
// file_path, file) — not just the first non-null one — to close the reversed-
// field bypass ({filePath:"innocuous", path:"plugin"} → ALLOW in prior code).
//
// A7/F5: targets are extracted from patch/apply_patch headers. When no targets
// can be extracted from any string field, the call is fail-closed (throw) rather
// than pass-through — a patch/apply_patch with no recognizable headers cannot
// be verified and must not proceed (F5 fail-closed).
//
// N5 (ML-5I5): patch/apply_patch — mention scan (first layer, before header
// extraction). ALL string-valued args are concatenated, backslash-normalized to
// "/" and lowercased; if any of the protected-path patterns appears in the text,
// the call is denied. Patterns: ".opencode/plugin", "opencode.json", and the
// global config dir (raw + realpathOrParent) followed by "/plugin" or
// "/opencode.json". This closes the git-apply -pN bypass: "+++ z/.opencode/
// plugins/x" extracts candidate "<projectDir>/z/.opencode/plugins/x" which is
// NOT under the protected dir after resolution (second layer misses it), but the
// raw text still contains ".opencode/plugin" which the mention layer catches.
//
// N6 (ML-5I6): two additions:
//   (a) The mention scan uses a second haystack (n5LowOct) where octal \NNN
//       sequences are decoded BEFORE the \ → / pass. This catches "+++ \"z/\056
//       opencode/plugins/x\"" (octal-encoded '.') and similar body-line forms.
//       The original haystack (n5Low) is kept so that Windows paths with literal
//       backslash-digit sequences (e.g. C:\Users\100x) are still matched by the
//       global-dir needle without false negative from octal misinterpretation.
//   (b) After extractPatchTargets populates candidates, each resolved candidate
//       string is scanned with the same needles (\ → /, lowercase). This catches
//       the case where unquoteGitPath decodes octals in the header token but the
//       resolved candidate escapes directory containment via a prefix (z/) as well
//       as dot-segment forms (z/.opencode/./plugins/x) that resolve to a path
//       containing ".opencode/plugin" even though the raw string does not.
//
// Comparison uses realpathOrParent for symlink resolution (F2/F8) and is
// case-insensitive on darwin and win32 (F2).
function selfProtect(tool, args, projectDir) {
  if (!FILE_WRITE_TOOLS.has(tool)) {
    return
  }

  // F7: collect ALL present path fields as candidates (not just filePath ?? path).
  var pathFieldNames = ["filePath", "path", "file_path", "file"]
  var candidates = []
  for (var pfi = 0; pfi < pathFieldNames.length; pfi++) {
    var v = args[pathFieldNames[pfi]]
    if (v != null && typeof v === "string") {
      candidates.push(nodePath.resolve(projectDir, v))
    }
  }

  // A7/F5: extract targets from patch/apply_patch headers.
  // Scan patchText and patch first (the canonical fields), then every remaining
  // string-valued own field — covers non-standard field names like "diff".
  if (tool === "patch" || tool === "apply_patch") {
    // N5 (ML-5I5): mention scan — first layer, before header extraction.
    // Concat ALL string-valued args, replace \ with /, lowercase, then search
    // for any protected-path pattern. Each arg is separated by "\n" to prevent
    // two adjacent fields from splicing into a false mention (e.g. "foo" + "bar"
    // vs. "foobar").
    //
    // N6 (ML-5I6-a): also build a second haystack (n5LowOct) with octal \NNN
    // sequences decoded BEFORE the \ → / pass. This handles "+++ \"z/\056opencode/
    // plugins/x\"" where \056 (octal '.') becomes '/' via the plain pass but '.'
    // via the octal-decode pass, so ".opencode/plugin" is matched in n5LowOct.
    var n5Text = ""
    var n5TextOct = ""
    for (var n5k in args) {
      if (Object.prototype.hasOwnProperty.call(args, n5k) && typeof args[n5k] === "string") {
        var n5v = args[n5k]
        n5Text += n5v.replace(/\\/g, "/") + "\n"
        // Decode octal \NNN sequences (same range as unquoteGitPath: [0-3][0-7][0-7])
        // using Buffer so multi-byte UTF-8 sequences (e.g. \302\251) are decoded
        // correctly as a unit rather than character by character.
        var n5Oct = n5v.replace(/\\([0-3][0-7]{2})/g, function(_, oct) {
          return String.fromCharCode(parseInt(oct, 8))
        })
        n5TextOct += n5Oct.replace(/\\/g, "/") + "\n"
      }
    }
    var n5Low = n5Text.toLowerCase()
    var n5LowOct = n5TextOct.toLowerCase()
    var n5GlobalDir = globalOpenCodeConfigDir()
    var n5GlobalNorm = n5GlobalDir.replace(/\\/g, "/").toLowerCase()
    var n5GlobalReal = ""
    try { n5GlobalReal = fs.realpathSync(n5GlobalDir).replace(/\\/g, "/").toLowerCase() } catch (n5e) {}
    var n5Patterns = [".opencode/plugin", "opencode.json",
      n5GlobalNorm + "/plugin", n5GlobalNorm + "/opencode.json"]
    if (n5GlobalReal && n5GlobalReal !== n5GlobalNorm) {
      n5Patterns.push(n5GlobalReal + "/plugin")
      n5Patterns.push(n5GlobalReal + "/opencode.json")
    }
    for (var n5i = 0; n5i < n5Patterns.length; n5i++) {
      if (n5Low.indexOf(n5Patterns[n5i]) !== -1 || n5LowOct.indexOf(n5Patterns[n5i]) !== -1) {
        throw new Error(
          "trackfw-guard: blocked — patch mentions a protected opencode path " +
          "and cannot be safely verified (D4 self-protection)"
        )
      }
    }

    // N7a (ML-5I7): block patches that declare symlink creation (mode 120000).
    // A symlink created under a protected directory could be used to escape the
    // directory-containment check via a dangling-symlink write in a second step
    // (N7b). Blocking mode 120000 closes the first step independently of the N7b
    // realpathOrParent fix, providing defence in depth.
    // The check runs against n5Text (all string-valued args, \ → /, lowercased) to
    // catch the declaration regardless of which field carries it.
    if (/^(new file mode|new mode)\s+120000\s*$/m.test(n5Text)) {
      throw new Error(
        "trackfw-guard: blocked — patch creates a symbolic link (mode 120000) " +
        "which cannot be safely verified (D4 self-protection)"
      )
    }

    var scannedKeys = {}
    var patchText = args.patchText != null ? args.patchText
      : (args.patch != null ? args.patch : null)
    if (patchText) {
      scannedKeys["patchText"] = true
      scannedKeys["patch"] = true
      var patchTargets = extractPatchTargets(patchText, projectDir)
      for (var pi = 0; pi < patchTargets.length; pi++) {
        candidates.push(patchTargets[pi])
      }
    }
    // Scan all remaining string fields not already scanned and not path fields.
    var knownPathKeys = {"filePath": true, "path": true, "file_path": true, "file": true}
    for (var k in args) {
      if (Object.prototype.hasOwnProperty.call(args, k) &&
          typeof args[k] === "string" &&
          !scannedKeys[k] &&
          !knownPathKeys[k]) {
        var extra = extractPatchTargets(args[k], projectDir)
        for (var ei = 0; ei < extra.length; ei++) {
          candidates.push(extra[ei])
        }
      }
    }
    // F5: fail-closed — patch/apply_patch with no extractable targets is not permitted.
    if (candidates.length === 0) {
      throw new Error(
        "trackfw-guard: blocked — patch/apply_patch with no recognizable target headers " +
        "cannot be verified and is not permitted (D4 fail-closed F5)"
      )
    }

    // N6 (ML-5I6-b): scan each resolved candidate string with the same mention
    // needles (\ → /, lowercase). Catches candidates decoded by unquoteGitPath
    // whose resolved path contains ".opencode/plugin" but whose z/ prefix defeated
    // the directory-containment check below, as well as dot-segment forms
    // (z/.opencode/./plugins/x) that resolve to a matching path even though the
    // raw text does not contain ".opencode/plugin" verbatim.
    for (var n6ci = 0; n6ci < candidates.length; n6ci++) {
      var n6candLow = candidates[n6ci].replace(/\\/g, "/").toLowerCase()
      for (var n6pi = 0; n6pi < n5Patterns.length; n6pi++) {
        if (n6candLow.indexOf(n5Patterns[n6pi]) !== -1) {
          throw new Error(
            "trackfw-guard: blocked — patch path decodes to a protected opencode path " +
            "and cannot be safely verified (D4 self-protection)"
          )
        }
      }
    }
  } else if (candidates.length === 0) {
    return
  }

  var globalDir = globalOpenCodeConfigDir()

  // Protected directories: any write under these is denied (F4).
  // N1: resolved via realpathOrParent so symlinked dirs (dotfile managers, etc.)
  // do not create a bypass.
  var rawProtectedDirs = [
    nodePath.dirname(realpathOrParent(__filename)),
    nodePath.resolve(projectDir, ".opencode", "plugins"),
    nodePath.resolve(projectDir, ".opencode", "plugin"),
    nodePath.resolve(globalDir, "plugins"),
    nodePath.resolve(globalDir, "plugin"),
  ]
  var resolvedDirs = rawProtectedDirs.map(function(d) { return realpathOrParent(d) })

  // Protected config files — also resolved via realpathOrParent (N1).
  var rawProtectedFiles = [
    nodePath.resolve(globalDir, "opencode.json"),
    nodePath.resolve(globalDir, "opencode.jsonc"),
    nodePath.resolve(projectDir, "opencode.json"),
    nodePath.resolve(projectDir, "opencode.jsonc"),
    nodePath.resolve(projectDir, ".opencode", "opencode.json"),
    nodePath.resolve(projectDir, ".opencode", "opencode.jsonc"),
  ]
  var resolvedFiles = rawProtectedFiles.map(function(f) { return realpathOrParent(f) })

  for (var ci = 0; ci < candidates.length; ci++) {
    var realC = realpathOrParent(candidates[ci])

    // Check protected directories (F4)
    for (var di = 0; di < resolvedDirs.length; di++) {
      if (isUnderDir(realC, resolvedDirs[di])) {
        throw new Error(
          "trackfw-guard: blocked — write to opencode plugin file is not permitted (D4 self-protection)"
        )
      }
      // N9 (ML-5I7): also deny when a protected dir is UNDER the candidate — covers
      // patches that delete or rename an ancestor directory such as "*** Delete File:
      // .opencode" or "rename from .opencode". If .opencode is deleted, the plugin
      // files it contains are also deleted.
      if (isUnderDir(resolvedDirs[di], realC)) {
        throw new Error(
          "trackfw-guard: blocked — write to opencode plugin file is not permitted (D4 self-protection)"
        )
      }
    }

    // Check protected config files
    for (var fi = 0; fi < resolvedFiles.length; fi++) {
      if (pathsEqual(realC, resolvedFiles[fi])) {
        throw new Error(
          "trackfw-guard: blocked — write to opencode config file is not permitted (D4 self-protection)"
        )
      }
    }
  }
}

/**
 * Calls trackfw guard <guardCmd> via spawnSync with an argv array.
 * Fail-closed: throws if result.error (ENOENT, ETIMEDOUT, etc.) OR status !== 0.
 *
 * @param {string} guardCmd   — "credential" or "git-branch"
 * @param {string} tool       — OpenCode tool ID
 * @param {object} args       — tool args
 * @param {string} projectDir — project root (where trackfw.yaml is)
 */
function runGuard(guardCmd, tool, args, projectDir) {
  // Resolve workdir (shell tool field) before using as cwd for git-branch guard
  var resolvedWorkdir = args.workdir
    ? nodePath.resolve(projectDir, args.workdir)
    : undefined

  // Build tool_input as a spread of args, including absolute file_path (D3)
  var toolInput = {}
  for (var k in args) {
    if (Object.prototype.hasOwnProperty.call(args, k)) {
      toolInput[k] = args[k]
    }
  }
  // F7: normalize file_path to absolute — filePath takes precedence over path
  if (args.filePath) {
    toolInput.file_path = nodePath.resolve(projectDir, args.filePath)
  } else if (args.path) {
    toolInput.file_path = nodePath.resolve(projectDir, args.path)
  }

  // Payload D3: hook_source:"opencode" enables the read scan in the Go guard
  var payload = {
    hook_source: "opencode",
    tool_name: tool,
    tool_input: toolInput,
    cwd: resolvedWorkdir || projectDir,
  }

  // credential guard: cwd = projectDir (checks trackfw.yaml directly)
  // git-branch guard: cwd = resolved workdir (FindProjectRoot walks up)
  var guardCwd = guardCmd === "credential"
    ? projectDir
    : (resolvedWorkdir || projectDir)

  // Extra flags: --global for credential guard when SCOPE is global
  var extraFlags = []
  if (guardCmd === "credential" && SCOPE === "global") {
    extraFlags = ["--global"]
  }

  // spawnSync with argv array — never via shell (D2 / D18)
  // timeout: 30 000 ms; expired → result.error.code = ETIMEDOUT → fail-closed
  var result = childProcess.spawnSync(
    "trackfw",
    ["guard", guardCmd].concat(extraFlags),
    {
      input: JSON.stringify(payload),
      encoding: "utf8",
      timeout: 30000,
      cwd: guardCwd,
    }
  )

  // Fail-closed: throw on any error (ENOENT, timeout, crash) or status !== 0
  if (result.error || result.status !== 0) {
    throw new Error(
      result.error
        ? "trackfw not found or timed out: " + result.error.message
        : (result.stderr || "").trim() || "trackfw guard " + guardCmd + ": operation blocked"
    )
  }
}

/**
 * Checks the tool and calls applicable guards (ADR D3, D7).
 * shell/bash:            credential + git-branch.
 * write/edit/patch/apply_patch: credential.
 * read/grep:             credential (hook_source="opencode" enables path check).
 * webfetch/websearch:    credential (URL/query and body may carry secrets; F6, ML-5I2).
 * Other tools: pass through without any call.
 */
function checkTools(tool, args, projectDir) {
  // Self-protection D4 — must run BEFORE the guard to fail fast
  selfProtect(tool, args, projectDir)

  if (SHELL_TOOLS.has(tool)) {
    runGuard("credential", tool, args, projectDir)
    runGuard("git-branch", tool, args, projectDir)
  } else if (FILE_WRITE_TOOLS.has(tool)) {
    runGuard("credential", tool, args, projectDir)
  } else if (FILE_READ_TOOLS.has(tool)) {
    runGuard("credential", tool, args, projectDir)
  } else if (WEBFETCH_TOOLS.has(tool)) {
    runGuard("credential", tool, args, projectDir)
  }
  // Tools outside the list: pass through without any call
}

module.exports = {
  id: "trackfw.guard",

  // V2 (OpenCode 2.x) — setup(ctx) called by the V2 loader
  // ctx.location.project.directory = project root (confirmed in packages/plugin/src/promise/plugin.ts@v2.3.0)
  setup: async function setup(ctx) {
    var projectDir = ctx.location.project.directory
    await ctx.tool.hook("execute.before", function(event) {
      checkTools(event.tool, event.input || {}, projectDir)
    })
  },

  // V1 (OpenCode 1.x) — server({directory, worktree}) called by the V1 loader
  // worktree = git root of the project (where trackfw.yaml is)
  server: async function server(input) {
    var worktree = input.worktree
    var directory = input.directory
    var projectDir = worktree || directory
    return {
      "tool.execute.before": async function(hookInput, hookOutput) {
        checkTools(hookInput.tool, hookOutput.args || {}, projectDir)
      },
    }
  },
}
